// Round-5: History filter, Analytics date sheet, More modern + search, view sheets + add/edit forms, DB explorer (attached onto S / S3 / S4),
// plus Advanced Analytics and Calculators & Tools (returned as S5). new Function('K','S','S3','S4', src)(K,S,S3,S4) -> S5
const {T,ty,caps,num,ic,a,card,group,lrow,chev,trailTxt,lic,cat,money,txn,btn,chip,seg,field,sw,cb,radio,lin,ring,bars,linec,donut,legend,split,stacked,ibtn,hdr,secH,menu,snack,dialog,sheet,search,fade,ptabs,utabs,slider,MONO} = K;
const {tileI,pill,amt,head,efab,ovMenu,scr,sec,emptyS,heroC,kv,dotL} = S3._;
const S5 = {};
const pinned = (t, inner) => `<div style="flex:none;padding:12px 20px 24px;background:${t.bg};border-top:1px solid ${t.olv};display:flex;gap:12px">${inner}</div>`;
const one = (b) => `<div style="display:flex;flex:1">${b}</div>`;
const navR = (t, i, l, v, o={}) => lrow(t,{lead:o.lead||tileI(t,i),sub:l,title:v,trail:o.trail??chev(t)});
const bigAmt = (t, v, c, l='Amount') => `<div style="padding:16px 20px;border-radius:20px;background:${t.c2};border:1px solid ${t.olv}"><div style="${ty('bS',t.onv)}">${l}</div><div style="display:flex;align-items:baseline;gap:6px;margin-top:2px"><span style="${ty('tL',t.onv)}">₹</span><span style="${ty('hL',c||t.on,num)}">${v}</span></div></div>`;
const swatches = (t, cs, sel=0) => `<div style="display:flex;gap:12px;flex-wrap:wrap">${cs.map((c,i)=>`<div style="width:36px;height:36px;border-radius:999px;background:${t.tone(c).viz};${i===sel?'box-shadow:0 0 0 2px '+t.bg+',0 0 0 4px '+t.p+';':''}"></div>`).join('')}</div>`;
const icons = (t, list, sel=0, c='#3B82F6') => `<div style="display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px">${list.map((i,j)=>`<div style="aspect-ratio:1/1;border-radius:12px;display:flex;align-items:center;justify-content:center;background:${j===sel?t.tone(c).cont:t.c2};${j===sel?'box-shadow:inset 0 0 0 2px '+t.tone(c).fg+';':'border:1px solid '+t.olv+';'}">${ic(i,22,j===sel?t.tone(c).fg:t.onv,j===sel?1:0)}</div>`).join('')}</div>`;
const chips = (t, list, sel=[]) => `<div style="display:flex;gap:8px;flex-wrap:wrap">${list.map((l,i)=>chip(t,l,{sel:sel.includes(i)})).join('')}</div>`;
const form = (t, title, secs, cta, o={}) => hdr(t,{back:1,close:1,title,acts:o.acts||[]}) + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:4px 20px 24px;display:flex;flex-direction:column;gap:24px;${o.top?'margin-top:-'+o.top+'px;':''}">${o.preview||''}${secs.map(([l,h])=>`<div>${l?secH(t,l):''}<div style="display:flex;flex-direction:column;gap:12px">${h}</div></div>`).join('')}</div></div>` + pinned(t, cta);
const viewSheet = (t, o) => sheet(t,{lead:o.lead,sub:o.sub,title:o.title,mh:o.mh||700,gap:20,body:o.body,actions:o.actions});
const infoR = (t, rows) => S.infoRows(t, rows);
const sw2 = (t, l, s, on) => lrow(t,{title:l,sub:s,trail:sw(t,on)});
const appear = (t, i, c, o={}) => lrow(t,{lead:`<div style="width:40px;height:40px;border-radius:12px;background:${t.tone(c).cont};display:flex;align-items:center;justify-content:center;flex:none">${i?ic(i,20,t.tone(c).fg,1):`<span style="width:18px;height:18px;border-radius:999px;background:${t.tone(c).viz}"></span>`}</div>`,sub:o.l||'Icon &amp; colour',title:o.v||'Tap to change',trail:chev(t)}).replace('min-height:72px','min-height:72px;background:'+t.c2+';border:1px solid '+t.olv+';border-radius:20px');
S5.picker = (t, mode='icon', o={}) => sheet(t,{title:mode==='icon'?'Choose icon':'Choose colour',mh:620,gap:16,body:`${o.both===false?'':ptabs(t,[['Icon','category'],['Colour','palette']],mode==='icon'?0:1)}${search(t,{ph:mode==='icon'?'Search icons':'Search colours',q:o.q,focus:!!o.q,filter:false})}${mode==='icon'?`<div>${secH(t,o.q?'Results':'Food &amp; drink')}${icons(t,o.q?['local_cafe','coffee','coffee_maker','emoji_food_beverage','local_bar','liquor']:['restaurant','local_cafe','fastfood','local_bar','bakery_dining','lunch_dining','local_pizza','icecream','ramen_dining','set_meal','liquor','kebab_dining'],0,o.c||'#EF4444')}</div>${o.q?'':`<div>${secH(t,'Shopping')}${icons(t,['shopping_bag','shopping_cart','storefront','checkroom','local_mall','redeem'],-1)}</div>`}`:`<div>${secH(t,'Colours')}${swatches(t,['#EF4444','#F97316','#F59E0B','#EAB308','#84CC16','#22C55E','#10B981','#14B8A6','#06B6D4','#0EA5E9','#3B82F6','#6366F1','#8B5CF6','#A855F7','#D946EF','#EC4899','#F43F5E','#64748B'],o.sel??10)}</div>`}`,actions:btn(t,'Done',{size:'l',full:1})});
S5.form = form;

// ---------------- History: advanced filters ----------------
S.histFilter = (t) => hdr(t,{back:1,close:1,title:'Filters',acts:[btn(t,'Clear all',{kind:'text'})]}) + `<div style="flex:1;overflow:hidden"><div style="padding:4px 20px 24px;display:flex;flex-direction:column;gap:24px">
<div>${secH(t,'Date range')}${navR(t,'calendar_today','Date range','Sep 1 - Oct 6, 2026').replace('min-height:72px','min-height:72px;background:'+t.c2+';border:1px solid '+t.olv+';border-radius:20px')}</div>
<div>${secH(t,'Transaction name')}${field(t,{lead:'search',ph:'Search via name'})}</div>
<div>${secH(t,'Type')}${chips(t,['Expense','Income','Transfer','Recurring'],[0])}</div>
<div>${secH(t,'Amount range')}<div style="display:flex;gap:12px"><div style="flex:1">${field(t,{label:'Min',value:'₹500'})}</div><div style="flex:1">${field(t,{label:'Max',ph:'Max'})}</div></div></div>
<div>${secH(t,'Accounts')}${chips(t,['HDFC Bank','ICICI Amazon Pay','Cash','Paytm Wallet'],[0])}</div>
<div>${secH(t,'Categories')}${chips(t,['Dining','Groceries','Rent','Fuel','Shopping','Utilities'],[0])}</div>
<div>${secH(t,'Tags')}${chips(t,['#trip','#family','#work','#personal'])}</div></div></div>` + pinned(t, one(btn(t,'Apply filters',{size:'l',full:1})));

// ---------------- Analytics: date range sheet + type menu ----------------
const cal = (t) => { const days = Array.from({length:30},(_,i)=>i+1); const lead=2; const inR=(d)=>d>=8&&d<=30; return `<div><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">${ibtn(t,'chevron_left',{kind:'std'})}<span style="${ty('tS',t.on)}">September 2026</span>${ibtn(t,'chevron_right',{kind:'std'})}</div><div style="display:grid;grid-template-columns:repeat(7,1fr);row-gap:4px;text-align:center">${['S','M','T','W','T','F','S'].map(d=>`<span style="${ty('bS',t.onv)};height:24px">${d}</span>`).join('')}${Array(lead).fill('<span></span>').join('')}${days.map(d=>{ const edge=d===8||d===30, r=inR(d); return `<div style="height:36px;display:flex;align-items:center;justify-content:center;${r&&!edge?'background:'+t.sc+';':''}${d===8?'background:linear-gradient(90deg,transparent 50%,'+t.sc+' 50%);':''}${d===30?'background:linear-gradient(90deg,'+t.sc+' 50%,transparent 50%);':''}"><span style="width:36px;height:36px;border-radius:999px;display:flex;align-items:center;justify-content:center;${edge?'background:'+t.p+';':''}${ty('bM',edge?t.op:r?t.osc:t.on,num)}">${d}</span></div>`; }).join('')}</div></div>`; };
S.dateSheet = (t) => sheet(t,{title:'Date range',mh:700,gap:16,body:`${chips(t,['This month','Last month','Last 3 months','Last 6 months','This year','All time','Custom'],[6])}<div style="display:flex;gap:12px"><div style="flex:1">${field(t,{label:'From',value:'Sep 8, 2026',focus:1})}</div><div style="flex:1">${field(t,{label:'To',value:'Sep 30, 2026'})}</div></div>${cal(t)}`,actions:btn(t,'Cancel',{kind:'outlined',size:'l',full:1})+btn(t,'Apply',{size:'l',full:1})});
S.typeMenu = (t) => `<div style="position:absolute;left:20px;top:132px;z-index:3">${menu(t,[{l:'All',sel:1},{i:'north_east',l:'Expense'},{i:'south_west',l:'Income'}],{w:184})}</div>`;

// ---------------- More: classic menu, modern layout, search ----------------
S.moreMenu = (t) => `<div style="position:absolute;top:96px;right:16px;z-index:3">${menu(t,[{l:'Classic',s:'Grouped lists',i:'view_agenda',sel:1},{l:'Modern',s:'Hero, grid and cards',i:'dashboard'}],{w:232})}</div>`;
S.moreModern = (t, o={}) => { const tile=(i,l,s)=>`<div style="padding:14px;border-radius:20px;background:${t.c2};border:1px solid ${t.olv};display:flex;flex-direction:column;gap:12px">${tileI(t,i)}<div><div style="${ty('tS',t.on)}">${l}</div><div style="${ty('bS',t.onv)}">${s}</div></div></div>`;
  const big=(i,l,s,k)=>`<div style="width:220px;flex:none;padding:16px;border-radius:24px;background:${k==='p'?t.pc:t.sc};display:flex;flex-direction:column;gap:24px">${ic(i,28,k==='p'?t.opc:t.osc,1)}<div><div style="${ty('tM',k==='p'?t.opc:t.osc)}">${l}</div><div style="${ty('bS',k==='p'?t.opc:t.osc)}">${s}</div></div></div>`;
  const parts=[`<div style="height:56px;padding:0 8px 0 16px;border-radius:16px;background:${t.sc};display:flex;gap:12px;align-items:center">${ic('workspace_premium',20,t.osc,1)}<span style="flex:1;${ty('tS',t.osc)}">Kuber Pro</span><span style="${ty('lL',t.osc)}">Upgrade</span>${ic('chevron_right',20,t.osc)}</div>`,
   sec(t,'Manage',`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${[['account_balance_wallet','Accounts','4 accounts'],['category','Categories','24 categories'],['label','Tags','6 tags'],['pie_chart','Budgets','4 active'],['sync','Recurring','5 rules'],['handshake','Ledger','3 open'],['account_balance','Loans','2 active'],['show_chart','Investments','5 holdings']].map(x=>tile(...x)).join('')}</div>`),
   sec(t,'Signature',`<div style="display:flex;gap:8px;overflow:hidden;margin-right:-20px">${big('auto_awesome','Ask Kuber','On-device smart assistant','p')}${big('sms','Import from SMS','Read bank SMS for transactions','s')}${big('bolt','Quick Add','Log in plain words','s')}</div><div style="display:flex;gap:6px;justify-content:center;margin-top:12px"><span style="width:16px;height:6px;border-radius:999px;background:${t.p}"></span><span style="width:6px;height:6px;border-radius:999px;background:${t.olv}"></span><span style="width:6px;height:6px;border-radius:999px;background:${t.olv}"></span></div>`),
   sec(t,'Tools',group(t,[['insert_chart','Advanced Analytics'],['calculate','Calculators &amp; Tools'],['sticky_note_2','Kuber Notes'],['credit_card','Kuber Cards'],['bolt','Quick Add'],['notifications_active','Reminders']].map(([i,l])=>lrow(t,{h:52,lead:lic(t,i,t.p),title:l,dense:1,trail:chev(t)})))),
   sec(t,'App',`<div style="display:flex;flex-wrap:wrap;gap:8px">${[['settings','Settings'],['storage','Data'],['notifications','Notifications'],['calendar_month','Upcoming Events'],['auto_stories','Stories'],['widgets','Widgets'],['info','About'],['security','Permissions']].map(([i,l])=>chip(t,l,{icon:i,ic:t.onv})).join('')}</div>`)];
  return hdr(t,{title:'More',acts:[ibtn(t,'search'),ibtn(t,'more_vert')]}) + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:4px 20px 120px;display:flex;flex-direction:column;gap:28px;${o.top?'margin-top:-'+o.top+'px':''}">${parts.join('')}</div></div>` + fade(t) + K.nav(t,3); };
S.moreSearch = (t) => `<div style="flex:none;padding:14px 16px 12px"><div style="height:48px;border-radius:999px;background:${t.c2};border:2px solid ${t.p};box-sizing:border-box;display:flex;align-items:center;padding:0 2px">${ibtn(t,'arrow_back',{kind:'std'})}<span style="flex:1;${ty('bL',t.on)}">bud<span style="display:inline-block;width:2px;height:20px;background:${t.p};vertical-align:-4px;margin-left:1px"></span></span>${ibtn(t,'close',{kind:'std',fg:t.onv})}</div></div><div style="flex:1;overflow:hidden;padding:0 20px;display:flex;flex-direction:column;gap:20px">${sec(t,'3 results',group(t,[['pie_chart','<b>Bud</b>gets','Manage · Track and control your monthly spending'],['tune','Edit Home Widgets','Settings · Budget snapshot widget'],['notifications','Notifications','App · Budget alerts']].map(([i,l,s])=>lrow(t,{lead:lic(t,i,t.p),title:l,sub:s,trail:chev(t)}))))}</div>`;

// ---------------- Accounts: add / edit ----------------
const accPreview = (t, n='HDFC Bank', b='₹50,000') => `<div style="padding:16px;border-radius:20px;background:${t.c2};border:1px solid ${t.olv};display:flex;gap:16px;align-items:center">${cat(t,'#3B82F6','account_balance',{s:48,g:24})}<div style="flex:1"><div style="${ty('tM',t.on)}">${n}</div><div style="${ty('bM',t.onv)}">Bank · Live preview</div></div>${amt(t,b)}</div>`;
S3.accForm = (t, o={}) => form(t, o.edit?'Edit Account':'Add Account', [
  ['Identity', field(t,{label:'Account name',value:'HDFC Bank',focus:!o.edit}) + chips(t,['Bank','Cash','Wallet','Credit card'],[o.cc?3:0])],
  ['Balance', o.cc? `<div style="display:flex;gap:12px"><div style="flex:1">${field(t,{label:'Credit limit',value:'₹1,00,000'})}</div><div style="flex:1">${field(t,{label:'Bill date',value:'12th'})}</div></div>` : field(t,{label:'Opening balance',value:'₹50,000',support:'What the account held when you started tracking'})],
  ['Appearance', appear(t,'account_balance','#3B82F6',{v:'Bank · Blue'})],
  ['', group(t,[sw2(t,'Set as default account','Pre-selected when you Quick Add',1), ...(o.edit?[sw2(t,'Disable account','Hidden from pickers, kept in history',0)]:[])])]
 ], one(btn(t,o.edit?'Save changes':'Save Account',{size:'l',full:1})), {preview:accPreview(t), acts:o.edit?[ibtn(t,'delete',{kind:'danger'})]:[], top:o.top});

// ---------------- Categories: add / edit ----------------
S3.catForm = (t, o={}) => form(t, o.edit?'Edit Category':'New Category', [
  ['Identity', field(t,{label:'Category name',value:'Dining',focus:1}) + navR(t,'folder','Group · optional','Food').replace('min-height:72px','min-height:72px;background:'+t.c2+';border:1px solid '+t.olv+';border-radius:20px')],
  ['Appearance', appear(t,'restaurant','#EF4444',{v:'Restaurant · Red'})],
  ['Type', ptabs(t,['Expense','Income','Both'],0)]
 ], one(btn(t,o.edit?'Save changes':'Save Category',{size:'l',full:1})), {preview:`<div style="padding:16px;border-radius:20px;background:${t.c2};border:1px solid ${t.olv};display:flex;gap:16px;align-items:center">${cat(t,'#EF4444','restaurant',{s:48,g:24})}<div style="flex:1"><div style="${ty('tM',t.on)}">Dining</div><div style="${ty('bM',t.onv)}">Expense · Food</div></div>${pill(t,'Live preview','n')}</div>`, acts:o.edit?[ibtn(t,'delete',{kind:'danger'})]:[]});

// ---------------- Tags: view + edit ----------------
S3.tagView = (t) => viewSheet(t,{lead:`<div style="width:48px;height:48px;border-radius:12px;background:${t.tone('#3B82F6').cont};display:flex;align-items:center;justify-content:center;flex:none">${ic('sell',24,t.tone('#3B82F6').fg,1)}</div>`,sub:'Tag',title:'#trip',mh:640,body:`${K.row ? '' : ''}${S.infoRows(t,[['Transactions','22'],['Spent with this tag','₹9,839'],['Last used','Oct 6 • 1:05 PM']])}<div>${secH(t,'Recent')}${group(t,[txn(t,{c:'#EF4444',i:'restaurant',name:'Tea/Coffee',sub:'Dining · Cash',type:'expense',amt:'80',time:'Oct 6'}),txn(t,{c:'#0EA5E9',i:'flight',name:'Goa flights',sub:'Travel · ICICI',type:'expense',amt:'8,420',time:'Sep 28'})])}</div><div style="display:flex">${btn(t,'View transactions',{kind:'outlined',icon:'receipt_long',size:'l',full:1})}</div>`,actions:btn(t,'Edit',{kind:'tonal',icon:'edit',size:'l',full:1})+btn(t,'Delete',{kind:'dangerTonal',icon:'delete',size:'l',full:1})});
S3.tagEdit = (t) => sheet(t,{title:'Edit Tag',mh:480,gap:20,body:`${field(t,{label:'Tag name',value:'#trip',focus:1,count:'5/20',support:' '})}<div>${appear(t,'','#3B82F6',{l:'Colour',v:'Blue'})}</div>${group(t,[sw2(t,'Disable tag','Hidden from pickers, kept on transactions',0)])}`,actions:btn(t,'Delete',{kind:'dangerTonal',size:'l',full:1})+btn(t,'Save',{size:'l',full:1})});

// ---------------- Budgets: view + add / edit ----------------
S3.budView = (t) => viewSheet(t,{lead:cat(t,'#F97316','shopping_bag',{s:48,g:24}),sub:'Budget · Every month',title:'Shopping',body:`<div style="display:flex;flex-direction:column;gap:10px"><div style="display:flex;align-items:baseline;gap:8px"><span style="${ty('hM',t.on,num)}">₹4,410</span><span style="${ty('bM',t.onv,num)}">of ₹5,000</span><span style="flex:1"></span>${pill(t,'Near limit','w')}</div>${lin(t,.88,'near')}<div style="${ty('lS',t.onv,'letter-spacing:.6px')}">RESETS IN 24 DAYS</div></div>${S.infoRows(t,[['Remaining','₹590'],['Daily pace','₹184 / day'],['Alerts','At 80% · At 100%']])}<div>${secH(t,'This period')}${group(t,[txn(t,{c:'#F97316',i:'shopping_bag',name:'Amazon',sub:'Shopping · HDFC Bank',type:'expense',amt:'1,299',time:'Oct 5'}),txn(t,{c:'#F97316',i:'shopping_bag',name:'Myntra',sub:'Shopping · ICICI',type:'expense',amt:'2,140',time:'Oct 2'})])}</div>`,actions:btn(t,'Edit',{kind:'tonal',icon:'edit',size:'l',full:1})+btn(t,'Delete',{kind:'dangerTonal',icon:'delete',size:'l',full:1})});
S3.budForm = (t, o={}) => form(t, o.edit?'Edit Budget':'Create Budget', [
  ['Select category', navR(t,'','Tap to change category','Shopping',{lead:cat(t,'#F97316','shopping_bag')}).replace('min-height:72px','min-height:72px;background:'+t.c2+';border:1px solid '+t.olv+';border-radius:20px')],
  ['Budget amount', bigAmt(t,'5,000')+`<div style="display:flex;gap:8px">${['3,000','5,000','8,000','10,000'].map((x,i)=>chip(t,'₹'+x,{sel:i===1,nocheck:1})).join('')}</div>`],
  ['Applies to', ptabs(t,['This month only','Every month'],1)],
  ['Budget alerts', group(t,[sw2(t,'At 80%','Notify when spending crosses 80%',1),sw2(t,'At 100%','Notify when the budget is used up',1)]) + `<div>${btn(t,'Add alert',{kind:'text',icon:'add'})}</div>`]
 ], one(btn(t,'Save Budget',{size:'l',full:1})), {acts:o.edit?[ibtn(t,'delete',{kind:'danger'})]:[]});

// ---------------- Recurring: view + add / edit ----------------
S3.recView = (t) => viewSheet(t,{lead:cat(t,'#E50914','movie',{s:48,g:24}),sub:'Recurring · Monthly',title:'Netflix',body:`<div>${money(t,'expense','649','hM')}</div>${S.infoRows(t,[['Next run','Oct 15, 2026'],['Account','Credit Card','credit_card',t.tone('#A855F7').fg],['Category','Entertainment','movie',t.tone('#E50914').fg],['Started','Jan 15, 2025'],['Ends','Never']])}<div>${secH(t,'History')}${group(t,[txn(t,{c:'#E50914',i:'movie',name:'Netflix',sub:'Recurring · Credit Card',type:'expense',amt:'649',time:'Sep 15'}),txn(t,{c:'#E50914',i:'movie',name:'Netflix',sub:'Recurring · Credit Card',type:'expense',amt:'649',time:'Aug 15'})])}</div>`,actions:btn(t,'Pause',{kind:'tonal',icon:'pause',size:'l',full:1})+btn(t,'Edit',{kind:'outlined',icon:'edit',size:'l',full:1})});
S3.recForm = (t, o={}) => form(t, o.edit?'Edit Recurring':'New Recurring', [
  ['Transaction', ptabs(t,[['Expense','north_east'],['Income','south_west']],0) + bigAmt(t,'649',t.exp,'Recurring expense amount') + field(t,{label:'Name',value:'Netflix'})],
  ['Where', group(t,[navR(t,'','Category','Entertainment',{lead:cat(t,'#E50914','movie')}),navR(t,'','Account','Credit Card',{lead:cat(t,'#A855F7','credit_card')})])],
  ['Schedule', `<div style="${ty('bS',t.onv)}">Frequency</div>`+chips(t,['Daily','Weekly','Monthly','Biweekly','Yearly','Custom'],[2]) + group(t,[navR(t,'event','Starts on','Oct 15, 2026')]) + `<div style="${ty('bS',t.onv)}">Ends</div>` + ptabs(t,['Never','After N','On date'],0)],
  ['Notes', field(t,{ph:'Optional · context, reference, anything',lead:'notes'})]
 ], one(btn(t,o.edit?'Save changes':'Save Recurring',{size:'l',full:1})), {top:o.top});

// ---------------- Ledger: view + add / edit ----------------
S3.ledView = (t) => viewSheet(t,{lead:`<div style="width:48px;height:48px;border-radius:999px;background:${t.tone('#3B82F6').cont};display:flex;align-items:center;justify-content:center;flex:none;${ty('tL',t.tone('#3B82F6').fg)}">R</div>`,sub:'Lent',title:'Rahul',body:`<div style="display:flex;flex-direction:column;gap:8px"><div style="${ty('bM',t.onv)}">Rahul owes you</div>${money(t,'income','1,200','hM')}${lin(t,.4)}<div style="${ty('bS',t.onv,num)}">₹800 of ₹2,000 repaid</div></div>${S.infoRows(t,[['Lent on','Sep 12, 2026'],['Account','HDFC Bank','account_balance',t.tone('#3B82F6').fg],['Due by','Oct 12, 2026']])}<div>${secH(t,'Payments')}${group(t,[lrow(t,{lead:tileI(t,'payments','i'),title:'₹800 received',sub:'Sep 30 · Cash',trail:''})])}</div>`,actions:btn(t,'Mark settled',{kind:'tonal',icon:'check',size:'l',full:1})+btn(t,'Record payment',{icon:'add',size:'l',full:1})});
