// =================== Advanced Analytics ===================
const AH = (t, title, o={}) => hdr(t,{back:1,title,acts:[ibtn(t,'info'),...(o.more?[ibtn(t,'more_vert')]:[])]});
const page = (t, title, parts, o={}) => AH(t,title,o) + `<div style="flex:1;overflow:hidden;position:relative"><div style="padding:4px 20px 32px;display:flex;flex-direction:column;gap:${o.gap??20}px;${o.top?'margin-top:-'+o.top+'px;':''}">${parts.join('')}</div></div>` + (o.over||'');
const note = (t, txt) => `<div style="display:flex;gap:8px;align-items:flex-start;${ty('bS',t.onv)}">${ic('info',16,t.onv)}<span>${txt}</span></div>`;
const rich = (t, a_, b, c='') => `<div style="${ty('bM',t.onv)}">${a_}<span style="color:${t.on};font-weight:600">${b}</span>${c}</div>`;
const rangeChip = (t, l='Last 6 months') => `<div style="display:flex;gap:8px">${chip(t,l,{icon:'calendar_today',ic:t.onv,drop:1})}</div>`;
