const yoyBars = (t) => bars(t,['J','F','M','A','M','J','J','A','S'].map((l,i)=>({l,v:[[42,38,45,40,52,48,50,47,44][i],[40,42,41,44,46,50,49,52,46][i]]})),{w:320,h:120,colors:[t.p,a(t.p,.32)],max:56,ticks:['0','28K','56K'],bw:7});
S5.yoy = (t) => page(t,'Year over year',[ptabs(t,['Total Spending','Total Income'],0), card(t,`${yoyBars(t)}<div style="height:12px"></div>${legend(t,[[t.p,'This year'],[a(t.p,.32),'Last year']])}`),
  card(t,kv(t,[['This year','₹4,06,200'],['Last year','₹4,10,000'],['Change','−0.9%',t.inc]])), rich(t,'Spending decreased by ','₹3,800',' compared with the same months last year.'),
  sec(t,'By category',group(t,[['#22C55E','home','Rent','₹1,62,000','0%'],['#EF4444','restaurant','Dining','₹58,400','+12%',1],['#10B981','local_grocery_store','Groceries','₹49,100','−6%'],['#64748B','local_gas_station','Fuel','₹22,300','−18%']].map(([c,i,n,v,ch,up])=>lrow(t,{lead:cat(t,c,i),title:n,sub:v,trail:`<span style="${ty('tS',up?t.exp:ch==='0%'?t.onv:t.inc,num)}">${ch}</span>`}))),seg(t,['Percent','Amount'],0,{check:false}).replace('height:40px','height:32px'))]);
