C.disc = (t,o) => calcPage(t,'Discount Calculator',[hero(t,'Final price','₹3,499','you save ₹1,500'), inputs(t,[inp(t,'Original price','₹4,999'),inp(t,'Discount','30%',.3)+chips(t,['10%','20%','30%','50%'],[2])]), saveBtn(t)],o);
